import { Topbar, TopbarItem, AppShell } from "@godxjp/ui/layout";
import { Button } from "@godxjp/ui/general";
import { Avatar, AvatarFallback } from "@godxjp/ui/data-display";
import { AppSettingPicker } from "@godxjp/ui/navigation";
import { PanelLeftClose, Search } from "lucide-react";

// The shell gives you slots; YOU decide what goes in them.
<AppShell
  sidebar={<MySidebar />}
  topbar={
    <Topbar
      start={
        <>
          <TopbarItem aria-label={t("toggleSidebar")} onClick={toggle}>
            <PanelLeftClose />
          </TopbarItem>
          <Avatar className="rounded-md">
            <AvatarFallback className="bg-primary text-primary-foreground font-bold">C</AvatarFallback>
          </Avatar>
        </>
      }
      center={
        <TopbarItem onClick={openSearch}>
          <Search />
          {t("search")}
        </TopbarItem>
      }
      end={
        <>
          <AppSettingPicker kind="locale" />
          <UserMenu />
        </>
      }
    />
  }
>
  {children}
</AppShell>
